"""Extract a ZIP archive into destination and return its member names."""
from pathlib import Path, PurePosixPath
from zipfile import ZipFile
import re
import stat

def extract(archive, destination):
    root = Path(destination).resolve()
    root.mkdir(parents=True, exist_ok=True)
    with ZipFile(archive) as source:
        members = source.infolist()
        for member in members:
            name = member.filename.replace("\\", "/")
            path = PurePosixPath(name)
            if path.is_absolute() or ".." in path.parts or re.match(r"^[A-Za-z]:", name):
                raise ValueError("unsafe archive path")
            if stat.S_ISLNK(member.external_attr >> 16):
                raise ValueError("archive links are forbidden")
            try:
                (root / name).resolve().relative_to(root)
            except ValueError as error:
                raise ValueError("archive path escapes destination") from error
        for member in members:
            target = root / member.filename.replace("\\", "/")
            if member.is_dir():
                target.mkdir(parents=True, exist_ok=True)
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(source.read(member))
        return source.namelist()
